class Solution {
    public int[] sortedSquares(int[] values) {
        int n = values.length, i = 0, j = n - 1;
        int[] out = new int[n];
        for (int k = n - 1; k >= 0; k--) {
            if (Math.abs(values[i]) > Math.abs(values[j])) { out[k] = values[i] * values[i]; i++; }
            else { out[k] = values[j] * values[j]; j--; }
        }
        return out;
    }
}

